"use client"

import * as React from "react"

import { useDigitRoll } from "@/lib/0db/use-digit-roll"
import { useComposedRefs } from "@/lib/0db/refs"
import { reader, raw } from "@/lib/0db/number"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { useFieldControl, useLineOrigin } from "@/components/ui/field"

type Unit = string | (Partial<Record<Intl.LDMLPluralRule, string>> & { other: string })

type NumberInputProps = Omit<React.ComponentProps<"input">, "type" | "value" | "defaultValue" | "min" | "max" | "step" | "size" | "onChange"> & {
  value?: number | null
  defaultValue?: number | null
  onValueChange?: (value: number | null) => void
  min?: number
  max?: number
  step?: number
  /** How the number reads when you're not typing it, passed to Intl.NumberFormat: { style: "currency", currency: "EUR" }. */
  format?: Intl.NumberFormatOptions
  /** The locale for reading and writing it. Fixed by default so the server and the browser agree on the first paint. */
  locale?: string
  /** Ours, after your figure, upright in pencil. Forms by plural category agree with the number: { one: "guest", other: "guests" }. */
  unit?: Unit
  /**
   * line: your figure on a field's baseline, less and more in brackets at its end. scale: your figure stands over a
   * ruler that hangs from the baseline; drag the ruler to turn the number, or step it and the ruler slides a tick.
   */
  variant?: "line" | "scale"
  /** Pins a state for documentation ("focus"); set on the root. */
  "data-force"?: string
}

const decimals = (n: number) => (String(n).split(".")[1] ?? "").length

/**
 * The formatted number, turned over like a counter's wheels: if it keeps its length only the figures that changed
 * turn, the units first and each place one arpeggio later; otherwise it turns over whole. `instant` skips the turn.
 */
function Figures({ text, value, instant }: { text: string; value: number | null; instant: boolean }) {
  const { shown: valueShown, whole, figs } = useDigitRoll(text, { order: value ?? 0, instant })
  const shown = String(valueShown)

  return (
    <span ref={whole} className="db-number-figures" aria-hidden="true">
      {[...shown].map((c, k) => (
        <span key={shown.length - k} ref={(el) => void (figs.current[k] = el)} className="db-number-figure">
          {c}
        </span>
      ))}
    </span>
  )
}

/**
 * A number on a baseline. Your figure is italic and reads formatted; type into it and you edit the plain figures.
 * Up and Down step it, Page Up and Page Down step ten, Home and End go to the ends; less and more do it by hand.
 * Each step turns the changed figures over like a counter.
 */
function NumberInput({
  value,
  defaultValue = null,
  onValueChange,
  min,
  max,
  step = 1,
  format,
  locale = "en",
  unit,
  variant = "line",
  name,
  disabled,
  readOnly,
  placeholder,
  className,
  onFocus,
  onBlur,
  onKeyDown,
  onPointerDown,
  "data-force": force,
  ref: forwardedRef, ...props
}: NumberInputProps) {
  const field = useFieldControl()
  const [own, setOwn] = React.useState<number | null>(defaultValue)
  const current = value !== undefined ? value : own
  const [typed, setDraft] = React.useState("")
  const [editing, setEditing] = React.useState(false)
  const [held, setHeld] = React.useState(false)
  const input = React.useRef<HTMLInputElement>(null)
  const composedRef = useComposedRefs(input, forwardedRef)
  const read = React.useMemo(() => reader(locale), [locale])
  const origin = useLineOrigin<HTMLInputElement>((el) => el.closest<HTMLElement>(".db-number") ?? el, { onPointerDown, onFocus } as React.ComponentProps<"input">)

  // While you type, the input holds what you typed; otherwise the plain figures of the value, whoever changed it.
  const draft = editing ? typed : raw(current, locale)

  const clamp = (n: number) => Math.min(max ?? Infinity, Math.max(min ?? -Infinity, n))
  const commit = (n: number | null) => {
    if (value === undefined) setOwn(n)
    if (!Object.is(n, current)) onValueChange?.(n)
  }
  /** Moves by whole steps from min (or zero), so 0.1 + 0.2 lands on 0.3 and not beside it. */
  const stepBy = (steps: number, from = current) => {
    if (disabled || readOnly) return
    const base = min ?? 0
    const places = Math.max(decimals(step), decimals(base))
    const at = from === null ? base : base + Math.round((from - base) / step + steps) * step
    commit(clamp(Number(at.toFixed(places))))
    setEditing(false)
  }

  // The figures you read take a true minus sign, not the hyphen the formatter gives.
  const text = current === null ? "" : new Intl.NumberFormat(locale, format).format(current).replace(/-/g, "\u2212")
  const forms = new Intl.PluralRules(locale)
  const said = unit === undefined ? "" : typeof unit === "string" ? unit : (unit[forms.select(current ?? 0)] ?? unit.other)
  const atMin = current !== null && min !== undefined && current <= min
  const atMax = current !== null && max !== undefined && current >= max

  const press = (steps: number) => ({
    tabIndex: -1,
    disabled: disabled || readOnly || (steps < 0 ? atMin : atMax),
    // Keeps focus (and the caret) where it was: the buttons are the hand's way in, the keys are the keyboard's.
    onPointerDown: (e: React.PointerEvent) => e.preventDefault(),
    onClick: () => stepBy(steps, editing ? (read(draft) ?? current) : current),
  })

  // scale: the ruler follows the hand, one step per tick, and the number with it.
  const drag = React.useRef<{ x: number; from: number | null } | null>(null)
  const pitch = 10 // px per step, as --db-number-pitch
  const tape = {
    onPointerDown(e: React.PointerEvent<HTMLElement>) {
      if (disabled || readOnly || e.button !== 0) return
      e.currentTarget.setPointerCapture(e.pointerId)
      drag.current = { x: e.clientX, from: current }
      setHeld(true)
    },
    onPointerMove(e: React.PointerEvent<HTMLElement>) {
      const d = drag.current
      if (!d) return
      stepBy(Math.round((d.x - e.clientX) / pitch), d.from)
    },
    onPointerUp() {
      drag.current = null
      setHeld(false)
    },
    onPointerCancel() {
      drag.current = null
      setHeld(false)
    },
  }

  return (
    <div
      data-slot="number-input"
      data-variant={variant}
      data-editing={editing ? "" : undefined}
      data-held={held ? "" : undefined}
      data-empty={current === null ? "" : undefined}
      data-force={force}
      className={cn("db-number", className)}
      style={{ "--at": ((current ?? 0) / step) % 100000 } as React.CSSProperties}
    >
      <span className="db-number-reading">
        <span className="db-number-cell">
          <input
            data-slot="number-input-control"
            {...props}
            ref={composedRef}
            className="db-number-input"
            type="text"
            inputMode={(min ?? -1) >= 0 && Number.isInteger(step) ? "numeric" : "decimal"}
            role="spinbutton"
            autoComplete="off"
            id={props.id ?? field.id}
            aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
            aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
            aria-valuenow={current ?? undefined}
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuetext={current === null ? undefined : `${text}${said ? ` ${said}` : ""}`}
            disabled={disabled}
            readOnly={readOnly}
            placeholder={placeholder}
            value={draft}
            onChange={(e) => {
              setEditing(true)
              setDraft(e.target.value)
              const n = read(e.target.value)
              if (n !== undefined) commit(n)
            }}
            onPointerDown={(e) => {
              origin.onPointerDown(e)
              if (disabled || readOnly || editing) return
              setDraft(draft) // a touch in the figures puts the caret among the plain ones
              setEditing(true)
            }}
            onFocus={origin.onFocus}
            onBlur={(e) => {
              onBlur?.(e)
              const n = read(draft)
              commit(n === undefined ? current : n === null ? null : clamp(n))
              setEditing(false)
            }}
            onKeyDown={(e) => {
              onKeyDown?.(e)
              if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey || e.nativeEvent.isComposing) return
              const from = editing ? (read(draft) ?? current) : current
              const keys: Record<string, () => void> = {
                ArrowUp: () => stepBy(1, from),
                ArrowDown: () => stepBy(-1, from),
                PageUp: () => stepBy(10, from),
                PageDown: () => stepBy(-10, from),
                ...(min !== undefined ? { Home: () => stepBy(0, min) } : {}),
                ...(max !== undefined ? { End: () => stepBy(0, max) } : {}),
                Enter: () => {
                  const n = read(draft)
                  commit(n === undefined ? current : n === null ? null : clamp(n))
                  setEditing(false)
                },
                Escape: () => setEditing(false),
              }
              const act = keys[e.key]
              if (!act || readOnly || disabled) return
              if (e.key !== "Enter") e.preventDefault()
              act()
            }}
          />
          <Figures text={text} value={current} instant={held} />
        </span>
        {said ? (
          <span className="db-number-unit" aria-hidden="true">
            {said}
          </span>
        ) : null}
      </span>
      <Button variant="bracket" className="db-number-less" aria-label="Less" {...press(-1)}>
        less
      </Button>
      <Button variant="bracket" className="db-number-more" aria-label="More" {...press(1)}>
        more
      </Button>
      {variant === "scale" ? <span className="db-number-tape" aria-hidden="true" {...tape} /> : null}
      {name ? <input type="hidden" name={name} value={current ?? ""} disabled={disabled} /> : null}
    </div>
  )
}

export { NumberInput, type NumberInputProps }

@layer components {
  /* ── db-number ── a number on a field's baseline: your figure in italic, formatted, turning over like a counter as it
     steps; less and more in brackets at the line's end. Typing shows the plain figures you edit. */
  .db-number {
    --db-number-pitch: 10px; /* one step of the scale's ruler; the script steps by the same */
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: baseline; column-gap: var(--db-space-1);
    font-size: var(--db-mp); line-height: 1.3;
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
  }
  .db-field > .db-number { grid-column: 1 / -1; }
  .db-number::after {
    content: ""; position: absolute; inset-inline: 0; bottom: 0; height: var(--db-stroke); background: var(--db-accent);
    scale: 0 1; transform-origin: var(--o, 0%) 50%; pointer-events: none; transition: scale var(--db-moderato) var(--db-exhale);
  }
  .db-number:focus-within::after, .db-number[data-force~="focus"]::after { scale: 1 1; }
  .db-number[data-force~="focus"] { outline: 0; }
  .db-number:has(.db-number-input[aria-invalid="true"]) { background-image: linear-gradient(var(--db-signal), var(--db-signal)); }
  .db-number:has(.db-number-input[aria-invalid="true"])::after { background: var(--db-signal); }
  .db-number:has(.db-number-input:disabled) { background-image: repeating-linear-gradient(90deg, var(--db-rule-strong) 0 2px, transparent 2px 6px); }

  .db-number-reading { display: flex; align-items: baseline; column-gap: 0.28em; min-width: 0; }
  /* The input and the figures share one cell: the figures are what you see, the input is what you edit. */
  .db-number-cell { display: grid; flex: 1; min-width: 0; direction: ltr; unicode-bidi: isolate; } /* figures read left to right on a right-to-left page too */
  .db-number-input, .db-number-figures {
    grid-area: 1 / 1; margin: 0; padding: 0.3em 0 0.42em;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.3;
    font-variant-numeric: lining-nums tabular-nums; color: var(--db-ink);
  }
  .db-number-input {
    appearance: none; width: 100%; min-width: 0; border: 0; border-radius: 0; outline: 0; background: none;
    color: transparent; caret-color: transparent;
  }
  .db-number-input::placeholder { font-family: var(--db-voice); font-style: normal; font-size: calc(1em / var(--db-expression-scale)); color: var(--db-pencil); opacity: 1; }
  .db-number:not([data-editing]) .db-number-input::selection { background: transparent; }
  .db-number[data-editing] .db-number-input { color: var(--db-ink); caret-color: var(--db-accent); }
  .db-number[data-editing] .db-number-figures { visibility: hidden; }
  .db-number-figures { pointer-events: none; white-space: pre; overflow: hidden; }
  .db-number-figure { display: inline-block; }
  .db-number:has(.db-number-input:disabled) .db-number-figures { color: var(--db-pencil); }
  .db-number-input:disabled { cursor: not-allowed; }
  /* Your figure is as wide as it is, so the unit follows it and the line reads as one phrase: 12 guests. */
  @supports (field-sizing: content) {
    .db-number-cell { flex: none; } /* your figure never gives way; the unit does */
    .db-number-input { field-sizing: content; min-width: 1ch; }
  }
  .db-number-unit { min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--db-pencil); white-space: nowrap; }
  .db-number > .db-btn { font-size: var(--db-p); }

  /* ── scale ── the dial's tuner, the ruler drawn small: your figure stands over the index, and the baseline is the edge of
     a ruler whose ticks hang from it, one per step, a longer one every ten. Stepping slides it a tick; drag it and it
     follows the hand. Figures and ruler read left to right in a right-to-left page too. */
  .db-number[data-variant="scale"] {
    direction: ltr; grid-template-columns: auto minmax(0, 1fr) auto; row-gap: var(--db-space-1); background: none;
  }
  .db-number[data-variant="scale"]::after { display: none; }
  .db-number[data-variant="scale"] > .db-number-less { grid-column: 1; grid-row: 1; }
  .db-number[data-variant="scale"] > .db-number-reading { grid-column: 2; grid-row: 1; justify-content: center; font-size: var(--db-f); line-height: 1; }
  .db-number[data-variant="scale"] :is(.db-number-input, .db-number-figures) { padding: 0; line-height: 1.1; text-align: center; letter-spacing: var(--db-f-tr); }
  .db-number[data-variant="scale"] .db-number-unit { font-size: var(--db-mp); }
  .db-number[data-variant="scale"] > .db-number-more { grid-column: 3; grid-row: 1; }
  .db-number-tape {
    --p: var(--db-number-pitch); --x: calc(50% - var(--at, 0) * var(--p) - 0.5px);
    grid-column: 1 / -1; grid-row: 2; position: relative; height: var(--db-space-5); cursor: ew-resize; touch-action: pan-y; user-select: none;
    background:
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 0 / 100% var(--db-hairline),
      repeating-linear-gradient(90deg, var(--db-pencil) 0 1px, transparent 1px calc(var(--p) * 10)) repeat-x calc(var(--x) + var(--p) * 5) 0 / calc(var(--p) * 10) 16px,
      repeating-linear-gradient(90deg, var(--db-rule-strong) 0 1px, transparent 1px var(--p)) repeat-x calc(var(--x) + var(--p) / 2) 0 / var(--p) 7px;
    mask-image: linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent);
    transition: background-position var(--db-moderato) var(--db-spiccato);
  }
  .db-number[data-held] .db-number-tape { transition: none; cursor: grabbing; }
  /* The index: an ink stroke standing through the ruler under your figure. Focus draws the accent along the edge. */
  .db-number-tape::before { content: ""; position: absolute; inset-inline: 22%; top: 0; height: var(--db-stroke); background: var(--db-accent); scale: 0 1; transform-origin: 50% 50%; transition: scale var(--db-moderato) var(--db-exhale); }
  .db-number:is(:focus-within, [data-force~="focus"]) .db-number-tape::before { scale: 1 1; }
  .db-number:has(.db-number-input[aria-invalid="true"]) .db-number-tape::before { scale: 1 1; background: var(--db-signal); }
  .db-number-tape::after { content: ""; position: absolute; left: calc(50% - var(--db-stroke) / 2); top: calc(var(--db-space-1) * -1); width: var(--db-stroke); height: calc(16px + var(--db-space-2)); background: var(--db-ink); }
  .db-number:has(.db-number-input:disabled) .db-number-tape { cursor: not-allowed; opacity: 0.45; }

  @media (forced-colors: active) {
    .db-number { forced-color-adjust: none; color: CanvasText; --db-paper: Canvas; --db-ink: CanvasText; --db-pencil: GrayText; --db-rule-strong: GrayText; --db-accent: Highlight; --db-signal: CanvasText; }
  }
}
